#include <stdio.h>
#include <stdlib.h>

// Define the structure for an edge in the graph
typedef struct {
    int vertex1;
    int vertex2;
    int weight;
} Edge;

// Define the structure for a disjoint set
typedef struct {
    int *parent;
    int size;
} DisjointSet;

// Function to find the parent of a vertex in the disjoint set
int find(DisjointSet *set, int vertex) {
    if (set->parent[vertex] == vertex) {
        return vertex;
    }
    return find(set, set->parent[vertex]);
}

// Function to union two vertices in the disjoint set
void unionVertices(DisjointSet *set, int vertex1, int vertex2) {
    int parent1 = find(set, vertex1);
    int parent2 = find(set, vertex2);
    if (parent1 != parent2) {
        set->parent[parent1] = parent2;
    }
}

// Function to calculate the minimum spanning tree using Kruskal's algorithm
void kruskal(Edge *edges, int numEdges, int numVertices) {
    DisjointSet set;
    set.parent = (int *)malloc(numVertices * sizeof(int));
    set.size = numVertices;
    for (int i = 0; i < numVertices; i++) {
        set.parent[i] = i;
    }
    int numEdgesInMST = 0;
    int totalWeight = 0;
    printf("weight=%d edges=", totalWeight);
    for (int i = 0; i < numEdges; i++) {
        int vertex1 = edges[i].vertex1;
        int vertex2 = edges[i].vertex2;
        int weight = edges[i].weight;
        if (find(&set, vertex1) != find(&set, vertex2)) {
            unionVertices(&set, vertex1, vertex2);
            totalWeight += weight;
            numEdgesInMST++;
            printf("%d-%d", vertex1, vertex2);
            if (numEdgesInMST < numVertices - 1) {
                printf(",");
            }
        }
    }
    printf("\n");
    free(set.parent);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }
    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        printf("Error opening file %s\n", argv[1]);
        return 1;
    }
    int numVertices;
    int numEdges;
    fscanf(file, "%d %d", &numVertices, &numEdges);
    Edge *edges = (Edge *)malloc(numEdges * sizeof(Edge));
    for (int i = 0; i < numEdges; i++) {
        fscanf(file, "%d %d %d", &edges[i].vertex1, &edges[i].vertex2, &edges[i].weight);
    }
    fclose(file);
    kruskal(edges, numEdges, numVertices);
    free(edges);
    return 0;
}
